-- Surroundings logic without WoW API calls, so the headless suite can run it: unpacking a zone
-- from the WowVision_Surroundings data addon, looking up the place at a position, the entry rule
-- (a place is announced only after the player has moved some distance inside it), and finding
-- the room indoors without a height.
--
-- Zone data (generated by wv-surroundings tools/export.py): a grid of cells `cell` yards wide,
-- row 0 at world x = `top` (north), column 0 at world y = `left` (west); each row a run-length
-- string "value*count,...". value = place id * 100 + direction code; code = template * 10 +
-- word (template from `dirs`, word from `compass`, or from `axes` for "running %s"); 0 = no data.
-- bridgeUnder: row, col, place triples said while swimming (water under bridges, city canals).
-- exits: x, y, width triples (ways out of city water). structs: names of structures with drop
-- edges; structCells: row, col, struct triples (their floors); edges: per drop edge
-- {struct, facing (compass index), drop yards, into water (0/1), piece, x1, y1, x2, y2, ...}:
-- points along the edge about 2 yd apart (a point set, not a line: thick or bent edges zigzag).
-- objects (things one bumps into), flat, 7 values each: x, y, half length and half width in
-- 0.1 yd, the long axis' angle in degrees (0 = north, toward west), name index into objectNames,
-- room (0 = outdoors).
-- piece 0: the floor lies low over the ground or water, nobody walks under it. Otherwise the edge
-- lies on a high floor piece (a gate's wall-walk, a bridge deck over a bank) that one can walk
-- under; there is no height on Forever, so the piece warns only after the player was seen
-- stepping onto it: pieceCells (row, col, piece: its footprint), access (piece, kind, x, y: 1
-- from the ground, 2 coming out of a building's rooms) and links (piece a, piece b: joined high
-- pieces, one walks from one onto the other).

local logic = {}
WowVision.surroundingsLogic = logic

-- Unpack the grid rows of a zone into run starts and values, once, on entry.
function logic.unpack(zone)
    if zone._rows then
        return
    end
    local rows = {}
    for r = 1, #zone.grid do
        local starts, values = {}, {}
        local col = 0
        for token in zone.grid[r]:gmatch("[^,]+") do
            local v, n = token:match("^(%d+)%*(%d+)$")
            if v == nil then
                v, n = token, 1
            end
            starts[#starts + 1] = col
            values[#values + 1] = tonumber(v)
            col = col + tonumber(n)
        end
        rows[r] = { starts = starts, values = values }
    end
    zone._rows = rows
    local under = {}
    local list = zone.bridgeUnder or {}
    for i = 1, #list - 2, 3 do
        under[list[i] * zone.cols + list[i + 1]] = list[i + 2]
    end
    zone._under = under
    local onStruct = {}
    list = zone.structCells or {}
    for i = 1, #list - 2, 3 do
        onStruct[list[i] * zone.cols + list[i + 1]] = list[i + 2]
    end
    zone._struct = onStruct
    local pieces = {}
    list = zone.pieceCells or {}
    for i = 1, #list - 2, 3 do
        local key = list[i] * zone.cols + list[i + 1]
        pieces[key] = pieces[key] or {}
        pieces[key][list[i + 2]] = true
    end
    zone._pieces = pieces
    local access = {}
    list = zone.access or {}
    for i = 1, #list - 3, 4 do
        local x, y = list[i + 2], list[i + 3]
        local key = math.floor((zone.top - x) / zone.cell) * zone.cols + math.floor((zone.left - y) / zone.cell)
        access[key] = access[key] or {}
        table.insert(access[key], { piece = list[i], kind = list[i + 1], x = x, y = y })
    end
    zone._access = access
    local links = {}
    list = zone.links or {}
    for i = 1, #list - 1, 2 do
        local a, b = list[i], list[i + 1]
        links[a] = links[a] or {}
        links[b] = links[b] or {}
        table.insert(links[a], b)
        table.insert(links[b], a)
    end
    zone._links = links
    -- a box per drop edge, so the edge search skips the far ones (cities have hundreds)
    local boxes = {}
    for i, e in ipairs(zone.edges or {}) do
        local x0, x1, y0, y1 = math.huge, -math.huge, math.huge, -math.huge
        for k = 6, #e - 1, 2 do
            x0, x1 = math.min(x0, e[k]), math.max(x1, e[k])
            y0, y1 = math.min(y0, e[k + 1]), math.max(y1, e[k + 1])
        end
        boxes[i] = { x0, x1, y0, y1 }
    end
    zone._edgeBoxes = boxes
    -- objects per grid cell (every cell their footprint's circle touches)
    local buckets = {}
    list = zone.objects or {}
    for i = 1, #list - 6, 7 do
        local x, y = list[i], list[i + 1]
        local reach = math.sqrt(list[i + 2] ^ 2 + list[i + 3] ^ 2) / 10
        local r0 = math.floor((zone.top - x - reach) / zone.cell)
        local r1 = math.floor((zone.top - x + reach) / zone.cell)
        local c0 = math.floor((zone.left - y - reach) / zone.cell)
        local c1 = math.floor((zone.left - y + reach) / zone.cell)
        for r = r0, r1 do
            for c = c0, c1 do
                local key = r * zone.cols + c
                buckets[key] = buckets[key] or {}
                table.insert(buckets[key], i)
            end
        end
    end
    zone._objects = buckets
    zone._waterStruct = {}
    for _, sid in ipairs(zone.waterStructs or {}) do
        zone._waterStruct[sid] = true
    end
end

-- Free the unpacked grid when the player leaves the zone.
function logic.pack(zone)
    zone._rows = nil
    zone._under = nil
    zone._struct = nil
    zone._pieces = nil
    zone._access = nil
    zone._links = nil
    zone._edgeBoxes = nil
    zone._rooms = nil
    zone._entrances = nil
    zone._regionOf = nil
    zone._objects = nil
    zone._waterStruct = nil
end

function logic.covers(zone, x, y)
    local r = math.floor((zone.top - x) / zone.cell)
    local c = math.floor((zone.left - y) / zone.cell)
    return r >= 0 and r < zone.rows and c >= 0 and c < zone.cols
end

-- Cell value at a world position (0 = no data), plus row and column.
function logic.valueAt(zone, x, y)
    local r = math.floor((zone.top - x) / zone.cell)
    local c = math.floor((zone.left - y) / zone.cell)
    if r < 0 or r >= zone.rows or c < 0 or c >= zone.cols then
        return 0, r, c
    end
    local row = zone._rows[r + 1]
    local starts = row.starts
    local lo, hi = 1, #starts
    while lo < hi do
        local mid = math.floor((lo + hi + 1) / 2)
        if starts[mid] <= c then
            lo = mid
        else
            hi = mid - 1
        end
    end
    return row.values[lo], r, c
end

-- The water under a bridge cell, as a place id (nil where there is none).
function logic.underBridge(zone, r, c)
    return zone._under and zone._under[r * zone.cols + c]
end

-- Compass index (1 = north, clockwise) of a world offset: dx north, dy west.
function logic.compassIndex(dx, dy)
    local angle = math.deg(math.atan2(-dy, dx)) % 360
    return math.floor((angle + 22.5) / 45) % 8 + 1
end

-- The nearest way out of the water within `reach` yards: index, distance, compass index.
function logic.nearestExit(zone, x, y, reach)
    local list = zone.exits or {}
    local best, bestD = nil, reach
    for i = 1, #list - 2, 3 do
        local dx, dy = list[i] - x, list[i + 1] - y
        local d = math.sqrt(dx * dx + dy * dy)
        if d <= bestD then
            best, bestD = i, d
        end
    end
    if best == nil then
        return nil
    end
    return (best + 2) / 3, bestD, logic.compassIndex(list[best] - x, list[best + 1] - y)
end

-- Is the cell (or a neighbour) part of the structure's floor?
local function onStructure(zone, r, c, struct)
    local cells = zone._struct
    if cells == nil then
        return false
    end
    for dr = -1, 1 do
        for dc = -1, 1 do
            if cells[(r + dr) * zone.cols + c + dc] == struct then
                return true
            end
        end
    end
    return false
end

logic.ACCESS_REACH = 2.5   -- yd from a place where a high piece is stepped onto from the ground
logic.ROOMS_REACH = 6.0    -- yd from where it joins a building, just after coming out of it

-- Is the cell (or a neighbour) part of a high piece's footprint?
local function onPiece(zone, r, c, piece)
    local cells = zone._pieces
    if cells == nil then
        return false
    end
    for dr = -1, 1 do
        for dc = -1, 1 do
            local set = cells[(r + dr) * zone.cols + c + dc]
            if set and set[piece] then
                return true
            end
        end
    end
    return false
end

-- Which high floor pieces the player is on (`on`, a set kept by the caller): a piece is entered
-- by passing where it is stepped onto from the ground, where it joins a building the player just
-- came out of (`cameOut`), or from a joined piece the player is on; it is left by walking off its
-- footprint. Walking under a piece never enters it.
function logic.updateHigh(zone, on, x, y, cameOut)
    local _v, r, c = logic.valueAt(zone, x, y)
    for piece in pairs(on) do
        if not onPiece(zone, r, c, piece) then
            on[piece] = nil
        end
    end
    local access = zone._access or {}
    local n = math.ceil(logic.ROOMS_REACH / zone.cell)
    for dr = -n, n do
        for dc = -n, n do
            for _, a in ipairs(access[(r + dr) * zone.cols + c + dc] or {}) do
                local d = math.sqrt((a.x - x) ^ 2 + (a.y - y) ^ 2)
                if (a.kind == 1 and d <= logic.ACCESS_REACH) or (a.kind == 2 and cameOut and d <= logic.ROOMS_REACH) then
                    on[a.piece] = true
                end
            end
        end
    end
    local links = zone._links or {}
    local added = true
    while added do
        added = false
        local new = {}
        for piece in pairs(on) do
            for _, other in ipairs(links[piece] or {}) do
                if not on[other] and onPiece(zone, r, c, other) then
                    new[#new + 1] = other
                end
            end
        end
        for _, piece in ipairs(new) do
            on[piece] = true
            added = true
        end
    end
    return on
end

-- The drop edge to warn about within `reach` yards: one the player stands in front of, on the
-- structure's floor (not beyond the edge); the edge index and distance. An edge on a high piece
-- counts only while the player is on that piece (`on`, see updateHigh). With `facing` (radians,
-- 0 = north, counter-clockwise, as GetPlayerFacing) an edge ahead (within 90 degrees of the
-- view) wins over a nearer one beside or behind. `skip`: a set of edge indexes left out (warned).
function logic.nearestEdge(zone, x, y, reach, on, facing, skip)
    local edges = zone.edges
    if edges == nil or #edges == 0 then
        return nil
    end
    local _v, r, c = logic.valueAt(zone, x, y)
    local vx, vy = nil, nil
    if facing then
        vx, vy = math.cos(facing), math.sin(facing)
    end
    local best, bestD, ahead, aheadD = nil, reach, nil, reach
    local boxes = zone._edgeBoxes or {}
    for i, e in ipairs(edges) do
        local struct = e[1]
        local fx, fy = logic.compassVector(e[2])
        local start = (e[5] == 0 or (on and on[e[5]])) and 6 or #e + 1
        local box = boxes[i]
        if (skip and skip[i]) or (box and (x < box[1] - reach or x > box[2] + reach or y < box[3] - reach or y > box[4] + reach)) then
            start = #e + 1
        end
        for k = start, #e - 1, 2 do
            local qx, qy = e[k], e[k + 1]
            local d = math.sqrt((x - qx) ^ 2 + (y - qy) ^ 2)
            -- in front of the edge: the drop lies ahead in the facing direction
            if (d <= bestD or d <= aheadD) and (x - qx) * fx + (y - qy) * fy <= 0.5 and onStructure(zone, r, c, struct) then
                if d <= bestD then
                    best, bestD = i, d
                end
                -- ahead in the view: toward the point, or, standing on it, toward the drop
                local dx, dy = qx - x, qy - y
                if d < 0.5 then
                    dx, dy = fx, fy
                end
                if vx and d <= aheadD and dx * vx + dy * vy >= 0 then
                    ahead, aheadD = i, d
                end
            end
        end
    end
    if ahead then
        return ahead, aheadD
    end
    return best, best and bestD
end

-- A drop edge in the player's path: moving along the unit vector (vx, vy), an edge point at most
-- `look` yards ahead and `width` yards beside the path, whose drop lies ahead (the path meets
-- the edge at 75 degrees or steeper, not running along it), with the player on the structure in
-- front of it. Returns the edge index and the distance along the path. `on` and `skip` as for
-- nearestEdge.
logic.AHEAD_WIDTH = 1.5
logic.AHEAD_ANGLE = 0.25   -- cosine: the path turns at most 75 degrees away from the drop

function logic.edgeAhead(zone, x, y, vx, vy, look, on, skip)
    local edges = zone.edges
    if edges == nil or #edges == 0 or look <= 0 then
        return nil
    end
    local _v, r, c = logic.valueAt(zone, x, y)
    local best, bestAlong = nil, look
    local boxes = zone._edgeBoxes or {}
    for i, e in ipairs(edges) do
        local fx, fy = logic.compassVector(e[2])
        local start = (e[5] == 0 or (on and on[e[5]])) and 6 or #e + 1
        local box = boxes[i]
        if (skip and skip[i]) or fx * vx + fy * vy < logic.AHEAD_ANGLE
            or (box and (x < box[1] - look or x > box[2] + look or y < box[3] - look or y > box[4] + look)) then
            start = #e + 1
        end
        for k = start, #e - 1, 2 do
            local dx, dy = e[k] - x, e[k + 1] - y
            local along = dx * vx + dy * vy
            if along > 0 and along <= bestAlong and math.abs(dx * vy - dy * vx) <= logic.AHEAD_WIDTH
                and -dx * fx - dy * fy <= 0.5 and onStructure(zone, r, c, e[1]) then
                best, bestAlong = i, along
            end
        end
    end
    return best, best and bestAlong
end

-- Distance from a position to the nearest point of a drop edge.
function logic.edgeDistance(zone, i, x, y)
    local e = zone.edges[i]
    local best = math.huge
    for k = 6, #e - 1, 2 do
        best = math.min(best, math.sqrt((x - e[k]) ^ 2 + (y - e[k + 1]) ^ 2))
    end
    return best
end

-- Degrees between the direction of a world offset (dx north, dy west) and a compass index's.
function logic.angleOff(dx, dy, index)
    local angle = math.deg(math.atan2(-dy, dx)) % 360
    local off = math.abs(angle - (index - 1) * 45) % 360
    return math.min(off, 360 - off)
end

-- Unit world vector (x north, y west) of a compass index.
function logic.compassVector(index)
    local angle = math.rad((index - 1) * 45)
    return math.cos(angle), -math.sin(angle)
end

-- The nearest cell within `reach` yards whose place kind is in `kinds` (a set): distance and
-- compass index toward it (from the cell centres), or nil.
function logic.nearestOfKinds(zone, x, y, kinds, reach)
    local _v, r0, c0 = logic.valueAt(zone, x, y)
    local n = math.ceil(reach / zone.cell)
    local best, bx, by = nil, nil, nil
    for dr = -n, n do
        for dc = -n, n do
            local cx = zone.top - (r0 + dr + 0.5) * zone.cell
            local cy = zone.left - (c0 + dc + 0.5) * zone.cell
            local d = math.sqrt((cx - x) ^ 2 + (cy - y) ^ 2)
            if d <= reach and (best == nil or d < best) then
                local v = logic.valueAt(zone, cx, cy)
                if kinds[logic.kind(zone, logic.placeOf(v))] then
                    best, bx, by = d, cx, cy
                end
            end
        end
    end
    if best == nil then
        return nil
    end
    return best, logic.compassIndex(bx - x, by - y)
end

function logic.placeOf(value)
    return math.floor(value / 100)
end

function logic.kind(zone, placeId)
    local p = zone.places[placeId]
    return p and p[1]
end

-- Spoken text for a cell value: the place label, and its direction and nearest road when wanted.
-- A place is {kind, label, nearest road (optional)}. `noNearRoad`: leave the stored nearest road
-- out (the caller says where the road is itself, after stepping off it).
function logic.describe(zone, value, withDirection, noNearRoad)
    local placeId = math.floor(value / 100)
    local p = zone.places[placeId]
    if p == nil then
        return nil
    end
    local text = p[2]
    local code = value % 100
    if withDirection and code > 0 then
        local template = zone.dirs[math.floor(code / 10)]
        local axis = template == "running %s"
        local word = (axis and zone.axes or zone.compass)[code % 10]
        if template and word then
            if axis then
                -- "road, northwest to southeast": the hyphenated axis runs together when spoken
                text = text .. ", " .. word:gsub("%-", " to ")
            else
                text = text .. ", " .. string.format(template, word)
            end
        end
    end
    -- the nearest road, fixed per place ("Goldshire road to the north")
    if withDirection and p[3] and not noNearRoad then
        text = text .. ", " .. p[3]
    end
    return text
end

-- Entry rule: a new key (place or room) counts only after the player has moved `distance`
-- yards while staying on it; the first key after a reset counts at once.
local Entry = {}
Entry.__index = Entry

function logic.newEntry(distance)
    return setmetatable({ distance = distance, current = nil }, Entry)
end

function Entry:reset()
    self.current, self.candidate, self.walked, self.lastX, self.lastY = nil, nil, 0, nil, nil
end

-- Returns the key when it becomes the current one, else nil.
-- `distanceFor(key)` (optional) gives a key its own distance (roads are narrow); the shorter of
-- the new key's and the current key's counts, so leaving a road is as quick as entering it.
function Entry:update(key, x, y)
    if key == nil then
        self.candidate = nil
        return nil
    end
    if self.current == nil then
        self.current, self.candidate = key, nil
        return key
    end
    if key == self.current then
        self.candidate = nil
        return nil
    end
    if key ~= self.candidate then
        self.candidate, self.walked, self.lastX, self.lastY = key, 0, x, y
    else
        local dx, dy = x - self.lastX, y - self.lastY
        self.walked = self.walked + math.sqrt(dx * dx + dy * dy)
        self.lastX, self.lastY = x, y
    end
    local distance = self.distance
    if self.distanceFor then
        distance = math.min(self.distanceFor(key) or distance, self.distanceFor(self.current) or distance)
    end
    if self.walked >= distance then
        self.current, self.candidate = key, nil
        return key
    end
    return nil
end

-- The nearest point of an object's footprint to a position, and the distance.
function logic.objectPoint(zone, i, x, y)
    local o = zone.objects
    local cx, cy = o[i], o[i + 1]
    local hu, hv = o[i + 2] / 10, o[i + 3] / 10
    local a = math.rad(o[i + 4])
    local ux, uy = math.cos(a), math.sin(a)
    local dx, dy = x - cx, y - cy
    local pu = math.max(-hu, math.min(hu, dx * ux + dy * uy))
    local pv = math.max(-hv, math.min(hv, -dx * uy + dy * ux))
    local qx, qy = cx + pu * ux - pv * uy, cy + pu * uy + pv * ux
    return qx, qy, math.sqrt((x - qx) ^ 2 + (y - qy) ^ 2)
end

logic.BUMP_REACH = 1.5    -- yd from the player to an object that can be what they push against
logic.BUMP_ANGLE = 0.34   -- cosine: the object lies at most 70 degrees off the way they push

-- The object the player pushes against: moving (or trying to) along the unit vector (vx, vy),
-- the nearest object within `reach` yards that lies that way. `room`: only objects of this room
-- (0 = outdoors). Returns the object's start index in zone.objects and its distance, or nil.
function logic.objectAhead(zone, x, y, vx, vy, reach, room)
    local buckets = zone._objects
    if buckets == nil then
        return nil
    end
    local _v, r, c = logic.valueAt(zone, x, y)
    local n = math.ceil(reach / zone.cell)
    local best, bestD, seen = nil, reach, {}
    for dr = -n, n do
        for dc = -n, n do
            for _, i in ipairs(buckets[(r + dr) * zone.cols + c + dc] or {}) do
                if not seen[i] and (room == nil or zone.objects[i + 6] == room) then
                    seen[i] = true
                    local qx, qy, d = logic.objectPoint(zone, i, x, y)
                    if d <= bestD and (d < 0.3 or ((qx - x) * vx + (qy - y) * vy) / d >= logic.BUMP_ANGLE) then
                        best, bestD = i, d
                    end
                end
            end
        end
    end
    return best, best and bestD
end

function logic.objectName(zone, i)
    return zone.objectNames and zone.objectNames[zone.objects[i + 5]]
end

-- Whose wall the player pushes against from outside: the interior whose room floor lies just
-- ahead (within `reach` yards along the vector), or a structure with drop edges (a gate, a wall,
-- a pier) whose floor lies there. Returns the name or nil.
function logic.wallOwner(zone, x, y, vx, vy, reach)
    for k = 0.5, reach, 0.5 do
        local px, py = x + vx * k, y + vy * k
        local found = logic.roomCandidates(zone, px, py, 0)
        local id = found[1] or logic.roomOutlineAt(zone, px, py)
        if id then
            local interior = zone.interiors[zone.rooms[id][1]]
            return interior and interior[1]
        end
        local _v, r, c = logic.valueAt(zone, px, py)
        local struct = zone._struct and zone._struct[r * zone.cols + c]
        -- the city water edges are a structure of their own (waterStructs): no wall
        if struct and not zone._waterStruct[struct] then
            return zone.structs[struct]
        end
    end
    return nil
end

-- Rooms: floor boxes per room and doors between rooms, built once per zone.
local function roomIndex(zone)
    if zone._rooms then
        return zone._rooms
    end
    local neighbours, byRoom = {}, {}
    for _, d in ipairs(zone.doors or {}) do
        local a, b = d[1], d[2]
        neighbours[a] = neighbours[a] or {}
        neighbours[b] = neighbours[b] or {}
        neighbours[a][b] = true
        neighbours[b][a] = true
        byRoom[a] = byRoom[a] or {}
        byRoom[b] = byRoom[b] or {}
        table.insert(byRoom[a], d)
        table.insert(byRoom[b], d)
    end
    zone._rooms = { neighbours = neighbours, doors = byRoom }
    return zone._rooms
end

logic.DOOR_REACH = 3.0   -- yards from a doorway's centre within which a crossing counts

-- Did the player walk through a doorway of the current room between the previous position and
-- this one? A door is {room a, room b, interior, centre x, y, facing nx, ny, side of room a},
-- in the building frame. Returns the room behind it (0 = outside) or nil.
function logic.crossedDoor(zone, current, px, py, x, y)
    if current == nil or px == nil then
        return nil
    end
    for _, d in ipairs(roomIndex(zone).doors[current] or {}) do
        local nx, ny, sideA = d[6], d[7], d[8]
        if sideA ~= 0 and (nx ~= 0 or ny ~= 0) then
            local interior = zone.interiors[d[3]]
            local ax, ay = logic.toBuilding(interior, px, py)
            local bx, by = logic.toBuilding(interior, x, y)
            local cx, cy = d[4], d[5]
            local near = function(u, v)
                return (u - cx) * (u - cx) + (v - cy) * (v - cy) <= logic.DOOR_REACH * logic.DOOR_REACH
            end
            if near(ax, ay) or near(bx, by) then
                local mine = current == d[1] and sideA or -sideA
                local before = ((ax - cx) * nx + (ay - cy) * ny) * mine
                local after = ((bx - cx) * nx + (by - cy) * ny) * mine
                if before > 0 and after < 0 then
                    return current == d[1] and d[2] or d[1]
                end
            end
        end
    end
    return nil
end

-- A world position in a building's own frame. The interior carries the frame
-- {name, ox, oy, scale, m00, m01, m10, m11}: world x = ox - scale * (m00 vx + m01 vy),
-- world y = oy - scale * (m10 vx + m11 vy). Room boxes are stored in that frame, so they stay
-- exact for rotated buildings.
function logic.toBuilding(interior, x, y)
    local ox, oy, s, a, b, c, d = interior[2], interior[3], interior[4], interior[5], interior[6], interior[7], interior[8]
    local r0, r1 = (ox - x) / s, (oy - y) / s
    local det = a * d - b * c
    return (d * r0 - b * r1) / det, (-c * r0 + a * r1) / det
end

-- The first room whose outline (the box of its walls, room[5], in the building frame) holds the
-- position, or nil: where the floor pieces leave gaps (under counters, a raised platform).
function logic.roomOutlineAt(zone, x, y)
    for id, room in ipairs(zone.rooms or {}) do
        local o = room[5]
        if o then
            local vx, vy = logic.toBuilding(zone.interiors[room[1]], x, y)
            if vx >= o[1] and vx <= o[3] and vy >= o[2] and vy <= o[4] then
                return id
            end
        end
    end
    return nil
end

-- Rooms whose floor boxes contain the position (within `margin` yards).
function logic.roomCandidates(zone, x, y, margin)
    margin = margin or 0.5
    local found, localPos = {}, {}
    for id, room in ipairs(zone.rooms or {}) do
        local pos = localPos[room[1]]
        if pos == nil then
            local vx, vy = logic.toBuilding(zone.interiors[room[1]], x, y)
            pos = { vx, vy }
            localPos[room[1]] = pos
        end
        local vx, vy = pos[1], pos[2]
        local b = room[4]
        for i = 1, #b - 3, 4 do
            if vx >= b[i] - margin and vx <= b[i + 2] + margin and vy >= b[i + 1] - margin and vy <= b[i + 3] + margin then
                found[#found + 1] = id
                break
            end
        end
    end
    return found
end

-- The room at a position: walking through a doorway of the current room leads into the room
-- behind it; otherwise the only candidate; or, where floors stack, the current room if it is a
-- candidate, else the one candidate joined to the current room by a door; else nil (unknown,
-- better quiet than wrong). px, py: the previous position (optional).
function logic.resolveRoom(zone, x, y, current, px, py)
    local crossed = logic.crossedDoor(zone, current, px, py, x, y)
    if crossed ~= nil then
        return crossed ~= 0 and crossed or nil
    end
    local cands = logic.roomCandidates(zone, x, y)
    if #cands == 0 then
        return nil
    end
    if #cands == 1 then
        return cands[1]
    end
    if current == nil then
        return nil
    end
    local joined = nil
    local neighbours = roomIndex(zone).neighbours[current] or {}
    for _, id in ipairs(cands) do
        if id == current then
            return current
        end
        if neighbours[id] then
            if joined ~= nil then
                return nil
            end
            joined = id
        end
    end
    return joined
end

-- A building-frame position in world yards (the inverse of toBuilding).
function logic.toWorld(interior, vx, vy)
    local ox, oy, s, a, b, c, d = interior[2], interior[3], interior[4], interior[5], interior[6], interior[7], interior[8]
    return ox - s * (a * vx + b * vy), oy - s * (c * vx + d * vy)
end

logic.ENTRANCE_MERGE = 4   -- yd; doorways of one building closer than this are one entrance

-- Entrances: the doorways between outside and a room, in world yards, built once per zone.
-- Each {x, y, text}: the building, and the room behind unless it is just the entrance.
function logic.entrances(zone)
    if zone._entrances then
        return zone._entrances
    end
    local list = {}
    for _, d in ipairs(zone.doors or {}) do
        local inside = d[1] == 0 and d[2] or d[2] == 0 and d[1] or nil
        local room = inside and zone.rooms[inside]
        local interior = zone.interiors[d[3]]
        if room and interior then
            local x, y = logic.toWorld(interior, d[4], d[5])
            local text = interior[1]
            if room[2] ~= "entrance" and room[2] ~= interior[1] then
                text = text .. ", " .. room[2]
            end
            local merged = false
            for _, e in ipairs(list) do
                if e.text == text and (e.x - x) ^ 2 + (e.y - y) ^ 2 < logic.ENTRANCE_MERGE ^ 2 then
                    merged = true
                    break
                end
            end
            if not merged then
                list[#list + 1] = { x = x, y = y, text = text, building = interior[1] }
            end
        end
    end
    zone._entrances = list
    return list
end

-- The nearest entrance within `reach` yards: index, distance, compass index toward it.
function logic.nearestEntrance(zone, x, y, reach)
    local best, bestD = nil, reach
    for i, e in ipairs(logic.entrances(zone)) do
        local d = math.sqrt((e.x - x) ^ 2 + (e.y - y) ^ 2)
        if d <= bestD then
            best, bestD = i, d
        end
    end
    if best == nil then
        return nil
    end
    local e = zone._entrances[best]
    return best, bestD, logic.compassIndex(e.x - x, e.y - y)
end

-- What lies around a place with no direction of its own (a city square): the things along its
-- border (streets, other squares, roads, bridges, canal walks, water, canals, drops) and the
-- building entrances on it, each said with its direction from the player on a north-up map. The
-- place's cells are found by a flood fill from the player's cell (one region per square, cached),
-- so nothing is cut up: a big square says the nearest things on entry and the others when the
-- player comes close to them. Terrain under a city (open land, hillside, forest) is no landmark.

logic.AROUND_PLACES = { square = true, hall = true }   -- plus streets without a direction
logic.WAYS = {
    street = true, square = true, hall = true, road = true, fork = true, crossing = true, bridge = true,
    quay = true, ["canal walk"] = true, ["slime canal walk"] = true, ["walk along the lava"] = true,
}
logic.WATER = { ["deep water"] = true, shore = true }
logic.DROPS = { ["cliff edge"] = true }
logic.MOUTH_MIN = 2        -- border cells at least that make a thing worth saying (about 8 yd)
logic.MOUTH_GAP = 2        -- cells; border pieces of one thing closer than this are one mouth
logic.REGION_MAX = 20000   -- cells; a flood fill stops there

-- Does a cell value belong to a place that says what lies around it?
function logic.isAroundPlace(zone, value)
    if value == nil or value == 0 then
        return false
    end
    local kind = logic.kind(zone, logic.placeOf(value))
    return logic.AROUND_PLACES[kind] or (kind == "street" and value % 100 == 0) or false
end

local function cellCentre(zone, r, c)
    return zone.top - (r + 0.5) * zone.cell, zone.left - (c + 0.5) * zone.cell
end

-- The thing a border cell shows: label and class ("way", "water", "drop", "canal"), or nil.
local function borderThing(zone, value, key)
    if value ~= 0 then
        local p = zone.places[logic.placeOf(value)]
        local kind = p and p[1]
        if logic.WAYS[kind] then
            return p[2], "way"
        elseif logic.WATER[kind] then
            return "water", "water"
        elseif logic.DROPS[kind] then
            return "cliff edge", "drop"
        end
        return nil
    end
    if zone._under and zone._under[key] then
        return "canal", "canal"
    end
    return nil
end

-- The region of the around-place at a position: {value, cells (set of keys), mouths}, where a
-- mouth is {label, class, points {x, y, ...}}; nil where the place is no around-place.
function logic.regionAt(zone, x, y)
    local value, r0, c0 = logic.valueAt(zone, x, y)
    if not logic.isAroundPlace(zone, value) then
        return nil
    end
    local cols = zone.cols
    zone._regionOf = zone._regionOf or {}
    local key0 = r0 * cols + c0
    if zone._regionOf[key0] then
        return zone._regionOf[key0]
    end
    local function at(r, c)
        if r < 0 or r >= zone.rows or c < 0 or c >= cols then
            return 0
        end
        local cx, cy = cellCentre(zone, r, c)
        return (logic.valueAt(zone, cx, cy))
    end
    local region = { value = value, label = zone.places[logic.placeOf(value)][2], cells = {}, mouths = {} }
    local cells = region.cells
    local stack, list = { r0, c0 }, {}
    cells[key0] = true
    local steps = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
    while #stack > 0 and #list < logic.REGION_MAX * 2 do
        local c = table.remove(stack)
        local r = table.remove(stack)
        list[#list + 1] = r
        list[#list + 1] = c
        for _, s in ipairs(steps) do
            local nr, nc = r + s[1], c + s[2]
            local key = nr * cols + nc
            if not cells[key] and at(nr, nc) == value then
                cells[key] = true
                stack[#stack + 1] = nr
                stack[#stack + 1] = nc
            end
        end
    end
    -- border cells per thing, then grouped into mouths (one per stretch of border)
    local byLabel, order, seen = {}, {}, {}
    for i = 1, #list - 1, 2 do
        local r, c = list[i], list[i + 1]
        for _, s in ipairs(steps) do
            local nr, nc = r + s[1], c + s[2]
            local key = nr * cols + nc
            if not cells[key] and not seen[key] then
                seen[key] = true
                local label, class = borderThing(zone, at(nr, nc), key)
                if label then
                    if byLabel[label] == nil then
                        byLabel[label] = { class = class, cells = {} }
                        order[#order + 1] = label
                    end
                    table.insert(byLabel[label].cells, { nr, nc })
                end
            end
        end
    end
    for _, label in ipairs(order) do
        local group = byLabel[label]
        local todo, done = group.cells, {}
        for i = 1, #todo do
            if not done[i] then
                done[i] = true
                local members, queue = { todo[i] }, { i }
                while #queue > 0 do
                    local a = todo[table.remove(queue)]
                    for j = 1, #todo do
                        if not done[j] and math.abs(todo[j][1] - a[1]) <= logic.MOUTH_GAP
                            and math.abs(todo[j][2] - a[2]) <= logic.MOUTH_GAP then
                            done[j] = true
                            members[#members + 1] = todo[j]
                            queue[#queue + 1] = j
                        end
                    end
                end
                if #members >= logic.MOUTH_MIN then
                    local points = {}
                    for _, m in ipairs(members) do
                        local px, py = cellCentre(zone, m[1], m[2])
                        points[#points + 1] = px
                        points[#points + 1] = py
                    end
                    table.insert(region.mouths, { label = label, class = group.class, points = points, cells = members })
                end
            end
        end
    end
    -- building entrances on the square or at its edge
    for _, e in ipairs(logic.entrances(zone)) do
        local _v, er, ec = logic.valueAt(zone, e.x, e.y)
        local near = false
        for dr = -1, 1 do
            for dc = -1, 1 do
                near = near or cells[(er + dr) * cols + ec + dc] == true
            end
        end
        if near then
            table.insert(region.mouths, { label = e.building, class = "entrance", points = { e.x, e.y } })
        end
    end
    for key in pairs(cells) do
        zone._regionOf[key] = region
    end
    return region
end

logic.LEADS_MAX = 5000   -- cells a way is followed to see where it leads; farther counts as leading on

-- Does the way behind a square's mouth lead on: does the thing (all cells of that name joined to
-- the mouth) meet another way than itself and the square? The ramps from the Valley of Heroes down
-- to the moat banks do not (they end at the shore); a street to the next district does. Cached.
function logic.leadsOn(zone, mouth, originLabel)
    if mouth.leads ~= nil then
        return mouth.leads
    end
    local cols = zone.cols
    local seen, stack, count = {}, {}, 0
    local function labelAt(r, c)
        if r < 0 or r >= zone.rows or c < 0 or c >= cols then
            return nil, nil
        end
        local cx, cy = cellCentre(zone, r, c)
        local p = zone.places[logic.placeOf((logic.valueAt(zone, cx, cy)))]
        return p and p[2], p and p[1]
    end
    for _, m in ipairs(mouth.cells or {}) do
        local key = m[1] * cols + m[2]
        if not seen[key] then
            seen[key] = true
            stack[#stack + 1] = m[1]
            stack[#stack + 1] = m[2]
        end
    end
    local leads = false
    while #stack > 0 and not leads do
        local c = table.remove(stack)
        local r = table.remove(stack)
        count = count + 1
        if count > logic.LEADS_MAX then
            leads = true
            break
        end
        for _, s in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
            local nr, nc = r + s[1], c + s[2]
            local key = nr * cols + nc
            if not seen[key] then
                local label, kind = labelAt(nr, nc)
                if label == mouth.label then
                    seen[key] = true
                    stack[#stack + 1] = nr
                    stack[#stack + 1] = nc
                elseif label and label ~= originLabel and logic.WAYS[kind] then
                    leads = true
                end
            end
        end
    end
    mouth.leads = leads
    return leads
end

-- Distance from a position to a mouth's nearest point, and the compass index toward it.
function logic.mouthDistance(mouth, x, y)
    local p = mouth.points
    local best, bx, by = math.huge, nil, nil
    for i = 1, #p - 1, 2 do
        local d = math.sqrt((p[i] - x) ^ 2 + (p[i + 1] - y) ^ 2)
        if d < best then
            best, bx, by = d, p[i], p[i + 1]
        end
    end
    return best, logic.compassIndex(bx - x, by - y)
end

logic.ITEM_DIRS = 2  -- directions per thing while walking (a street meeting a square in five places)
logic.HERE = 2   -- yd; closer than this a thing is "here", without a direction

-- Items from a list of {label, class, distance d, compass index dir} entries: one item per label
-- with its compass indexes (nearest first, no repeats, at most `maxDirs`; closer than HERE none),
-- items nearest first.
local function groupItems(found, maxDirs)
    table.sort(found, function(a, b)
        return a.d < b.d
    end)
    local items, byLabel = {}, {}
    for _, f in ipairs(found) do
        local item = byLabel[f.label]
        if item == nil then
            item = { label = f.label, class = f.class, d = f.d, dirs = {}, mouths = {} }
            byLabel[f.label] = item
            items[#items + 1] = item
        end
        local dir = f.d >= logic.HERE and f.dir or nil
        local known = false
        for _, v in ipairs(item.dirs) do
            known = known or v == dir
        end
        if dir and not known and #item.dirs < (maxDirs or math.huge) then
            item.dirs[#item.dirs + 1] = dir
        end
        if f.mouth then
            item.mouths[#item.mouths + 1] = f.mouth
        end
    end
    return items
end

-- At most `max` items (nil: all); with more, the item labelled `cameFrom` goes first.
local function capItems(items, max, cameFrom)
    if max == nil or #items <= max then
        return items
    end
    local out = {}
    for _, item in ipairs(items) do
        if item.label ~= cameFrom then
            out[#out + 1] = item
        end
    end
    while #out > max do
        table.remove(out)
    end
    return out
end

-- What lies around the player on the region: items {label, class, dirs, mouths}, nearest first.
-- opts (all optional): max (items), cameFrom (the label that goes first when there are more),
-- dirs (directions per item at most), said (a set of mouths left out: already said), classes
-- (a set: only these classes), leading (with zone: only ways that lead on, see leadsOn).
function logic.aroundItems(region, x, y, opts)
    opts = opts or {}
    local found = {}
    for _, m in ipairs(region.mouths) do
        if not (opts.said and opts.said[m]) and (opts.classes == nil or opts.classes[m.class])
            and not (opts.leading and m.class == "way" and not logic.leadsOn(opts.zone, m, region.label)) then
            local d, dir = logic.mouthDistance(m, x, y)
            found[#found + 1] = { label = m.label, class = m.class, d = d, dir = dir, mouth = m }
        end
    end
    return capItems(groupItems(found, opts.dirs), opts.max, opts.cameFrom)
end

-- Mouths of the region not yet said (`said`, a set kept by the caller) that the player has come
-- within `reach` yards of, nearest first, as items; they are marked said. Entrances are left to
-- the entrance guidance.
function logic.approaching(region, x, y, reach, said, maxDirs)
    local found = {}
    for _, m in ipairs(region.mouths) do
        if not said[m] and m.class ~= "entrance" then
            local d, dir = logic.mouthDistance(m, x, y)
            if d <= reach then
                said[m] = true
                found[#found + 1] = { label = m.label, class = m.class, d = d, dir = dir, mouth = m }
            end
        end
    end
    return groupItems(found, maxDirs)
end

-- The middle of a room's floor boxes (building frame), area weighted.
local function roomMiddle(room)
    local b = room[4]
    local sx, sy, n = 0, 0, 0
    for i = 1, #b - 3, 4 do
        local a = math.max((b[i + 2] - b[i]) * (b[i + 3] - b[i + 1]), 0.01)
        sx, sy, n = sx + (b[i] + b[i + 2]) / 2 * a, sy + (b[i + 1] + b[i + 3]) / 2 * a, n + a
    end
    if n == 0 then
        return nil
    end
    return sx / n, sy / n
end

-- The direction of a doorway seen from a room: the way one passes through it leaving the room
-- (its plane's normal, away from the room's side), a compass index. Fixed per room and doorway,
-- like the map: the auction house's way out is to the east from anywhere in the hall. Without a
-- usable plane (a flat opening), the way from the room's middle to the doorway.
function logic.doorwayDirection(zone, d, roomId)
    local interior = zone.interiors[d[3]]
    if interior == nil then
        return nil
    end
    local cx, cy, nx, ny, sideA = d[4], d[5], d[6], d[7], d[8]
    local vx, vy
    if sideA ~= 0 and (nx ~= 0 or ny ~= 0) then
        -- room a lies on the side sideA of the normal, room b on the other one
        local side = roomId == d[1] and sideA or -sideA
        vx, vy = -side * nx, -side * ny
    else
        local room = zone.rooms[roomId]
        local mx, my = nil, nil
        if room then
            mx, my = roomMiddle(room)
        end
        if mx == nil then
            return nil
        end
        vx, vy = cx - mx, cy - my
        if vx * vx + vy * vy < 0.01 then
            return nil
        end
    end
    local ax, ay = logic.toWorld(interior, cx, cy)
    local bx, by = logic.toWorld(interior, cx + vx, cy + vy)
    return logic.compassIndex(bx - ax, by - ay)
end

-- The doorways of a room as items {label, class ("room" or "out"), dirs}: the room behind each
-- (0 = the way out) with the fixed direction of its doorways (doorwayDirection); the way out
-- first, then the other rooms in the data's order, so a room always says the same. opts
-- (optional): max, dirs as for aroundItems; cameFrom: the room the player came from (a room id,
-- 0 = outside), left out first when there are more than max.
function logic.roomDoorways(zone, roomId, opts)
    opts = opts or {}
    if zone.rooms[roomId] == nil then
        return {}
    end
    local list = roomIndex(zone).doors[roomId] or {}
    local ordered = {}
    for pass = 1, 2 do
        for _, d in ipairs(list) do
            if ((d[1] == 0 or d[2] == 0) and 1 or 2) == pass then
                ordered[#ordered + 1] = d
            end
        end
    end
    local items, byLabel, cameLabel = {}, {}, nil
    for _, d in ipairs(ordered) do
        local other = d[1] == roomId and d[2] or d[1]
        local label, class = "out", "out"
        if other ~= 0 then
            label, class = logic.describeRoom(zone, other, roomId), "room"
        end
        if label then
            if other == opts.cameFrom then
                cameLabel = label
            end
            local item = byLabel[label]
            if item == nil then
                item = { label = label, class = class, dirs = {} }
                byLabel[label] = item
                items[#items + 1] = item
            end
            local dir = logic.doorwayDirection(zone, d, roomId)
            local known = false
            for _, v in ipairs(item.dirs) do
                known = known or v == dir
            end
            if dir and not known and #item.dirs < (opts.dirs or math.huge) then
                item.dirs[#item.dirs + 1] = dir
            end
        end
    end
    return capItems(items, opts.max, cameLabel)
end

-- Cliffs and water around an outdoor place: per class (from `classOf`, kind -> class word) the
-- nearest cells within `reach` yards, as items {label, class, dirs, d}: up to 2 directions that
-- are not neighbours on the compass ("cliff edge to the west and north", not "west and
-- northwest"), items nearest first. `skip`: a set of classes left out (the place itself, the
-- place the player came from).
function logic.featuresAround(zone, x, y, reach, classOf, skip)
    local _v, r0, c0 = logic.valueAt(zone, x, y)
    local n = math.ceil(reach / zone.cell)
    local sectors = {}   -- class -> compass index -> nearest distance
    for dr = -n, n do
        for dc = -n, n do
            local cx, cy = cellCentre(zone, r0 + dr, c0 + dc)
            local d = math.sqrt((cx - x) ^ 2 + (cy - y) ^ 2)
            if d <= reach and d >= zone.cell / 2 then
                local v = logic.valueAt(zone, cx, cy)
                local class = v ~= 0 and classOf[logic.kind(zone, logic.placeOf(v))]
                if class and not (skip and skip[class]) then
                    local byDir = sectors[class] or {}
                    sectors[class] = byDir
                    local dir = logic.compassIndex(cx - x, cy - y)
                    if byDir[dir] == nil or d < byDir[dir] then
                        byDir[dir] = d
                    end
                end
            end
        end
    end
    local items = {}
    for class, byDir in pairs(sectors) do
        local list = {}
        for dir, d in pairs(byDir) do
            list[#list + 1] = { dir = dir, d = d }
        end
        table.sort(list, function(a, b)
            return a.d < b.d
        end)
        local dirs = {}
        for _, s in ipairs(list) do
            local apart = true
            for _, dir in ipairs(dirs) do
                local gap = math.abs(s.dir - dir) % 8
                apart = apart and math.min(gap, 8 - gap) >= 2
            end
            if apart and #dirs < 2 then
                dirs[#dirs + 1] = s.dir
            end
        end
        items[#items + 1] = { label = class, class = class, dirs = dirs, d = list[1].d }
    end
    table.sort(items, function(a, b)
        return a.d < b.d
    end)
    return items
end

-- Spoken text for a room: the interior's name when it changes, then the room.
function logic.describeRoom(zone, roomId, previousRoomId)
    local room = zone.rooms[roomId]
    if room == nil then
        return nil
    end
    local previous = previousRoomId and zone.rooms[previousRoomId]
    if previous == nil or previous[1] ~= room[1] then
        local interior = zone.interiors[room[1]]
        return (interior and interior[1] or "") .. ", " .. room[2]
    end
    return room[2]
end

return logic
